import heapq


def dependency_solver(name_order, preference):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=(name_order == "descending"))
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name])
            if preference == "maximum":
                versions.reverse()
            # The absent coordinate is -1: first for minimization, last for maximization.
            choices.append(([None] + versions) if preference == "minimum"
                            else versions + [None])

        best_key = None
        best = None
        for vector in product(*choices):
            selected = dict(zip(names, vector))
            if any(selected[name] is None or not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            if any(selected[name] is not None and selected[name] != version
                   for name, version in pins.items()):
                continue
            if any(selected[name] in blocked.get(name, [])
                   for name in names if selected[name] is not None):
                continue

            rows = {}
            edges = {name: [] for name in names if selected[name] is not None}
            valid = True
            for name in edges:
                row = next((r for r in packages[name]
                            if r["version"] == selected[name]), None)
                if row is None:
                    valid = False
                    break
                rows[name] = row
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    version = selected[target]
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            active, finished = set(), set()
            def visit(node):
                if node in active:
                    return False
                if node in finished:
                    return True
                active.add(node)
                for child in edges[node]:
                    if not visit(child):
                        return False
                active.remove(node)
                finished.add(node)
                return True

            if not all(visit(node) for node in edges):
                continue
            reachable = set()
            stack = list(roots)
            while stack:
                node = stack.pop()
                if node in reachable:
                    continue
                reachable.add(node)
                stack.extend(edges[node])
            if reachable != set(edges):
                continue

            key = tuple(-1 if selected[n] is None else selected[n] for n in names)
            if best_key is None or (key < best_key if preference == "minimum"
                                    else key > best_key):
                best_key = key
                best = {n: selected[n] for n in names if selected[n] is not None}
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def solve_ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        if mode == "floor":
            return n // d
        return (n + d // 2) // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def solve_jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(available, k):
        ids = {job["id"] for job in subset}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in subset)
        chosen_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and chosen_ids < best_ids)):
            best_value, best_ids = value, chosen_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def solve_routes(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    def mark(node):
        mask = 0
        for i, required_node in enumerate(required):
            if node == required_node:
                mask |= 1 << i
        return mask

    source, start, coupons = data["source"], data["start"], data["coupons"]
    initial = (source, mark(source), coupons)
    dist = {initial: start}
    queue = [(start, source, initial[1], coupons)]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | mark(next_node)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
    return {"arrival": None}


